     * @return int table offset
     */
    public static function endWXF(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // FIELD_ID
        $builder->required($o, 44);  // GRID
        return $o;
    }

